#!/bin/bash
# This file was generated by Cursor AI on 2026-11-17.
#
# Generate egglog rewrite files for C2PO:
#   prepare (equiv) -> egglog/rewrites/{temporal,const_folding,extended}.egg
#
# Usage: ./generate_egg.sh

set -euo pipefail

SCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
SCRIPTS_DIR=$(cd "$SCRIPT_DIR/.." && pwd)
COMPILER_DIR=$(cd "$SCRIPTS_DIR/.." && pwd)

EGGLOG_OUT="$COMPILER_DIR/c2po/egglog/rewrites"

cd "$SCRIPT_DIR"

"$SCRIPT_DIR/prepare.sh"

echo "==> Generating egglog rewrite files"
PYTHONPATH="$COMPILER_DIR${PYTHONPATH:+:$PYTHONPATH}" \
  python3 "$SCRIPTS_DIR/generate_egglog.py" \
  equiv/ rewrites.json "$EGGLOG_OUT"

echo "==> Egg generation complete"
echo "    egg: $EGGLOG_OUT/{temporal,const_folding,extended}.egg"
